// Sends the exact request bytes (base64) and the Shopify headers to Supabase.
// No secret here and no signature check here: Supabase verifies the HMAC before anything is written.
// Webhook node 'Raw Body' = on puts req.rawBody (the untouched bytes) in binary property 'data'.
const item = $input.first();
const h = item.json.headers || {};
if (!item.binary || !item.binary.data) {
  throw new Error('Raw body missing - enable Raw Body on the Webhook node');
}
// getBinaryDataBuffer works for both in-memory and filesystem binary storage modes
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { rpc: {
  p_raw_body_b64: raw.toString('base64'),
  p_hmac: h['x-shopify-hmac-sha256'] ?? null,
  p_topic: h['x-shopify-topic'] ?? null,
  p_event_id: h['x-shopify-event-id'] ?? null,
  p_shop_domain: h['x-shopify-shop-domain'] ?? null,
  p_triggered_at: h['x-shopify-triggered-at'] ?? null,
} } }];

// Keeps only the outcome. Supabase or network failures become 500 so Shopify retries.
const r = $input.first().json;
const b = r.body || {};
if (r.statusCode === 200 && typeof b.http_status === 'number') {
  return [{ json: { status: b.http_status, outcome: b.outcome } }];
}
return [{ json: { status: 500, outcome: 'supabase_call_failed', supabase_status: r.statusCode ?? null } }];
